begin;
create or replace function mblite_access_private.community_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from mblite_access_private.admins a join auth.users u on u.id=a.user_id where a.user_id=auth.uid() and u.email_confirmed_at is not null and not u.is_anonymous) $$;
revoke all on function mblite_access_private.community_admin() from public,anon,authenticated;
grant execute on function mblite_access_private.community_admin() to authenticated;
create table public.mblite_forum(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,author text not null check(length(author) between 1 and 40),title text not null check(length(title) between 1 and 120),body text not null check(length(body) between 1 and 4000),tag text not null check(length(tag) between 1 and 80),image_data text check(length(image_data)<=450000 and image_data ~ '^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$'),parent_id uuid references public.mblite_forum on delete cascade,created_at timestamptz not null default now(),suspended boolean not null default false);
create index on public.mblite_forum(parent_id,created_at desc);
alter table public.mblite_forum enable row level security;
revoke all on public.mblite_forum from public,anon,authenticated;
grant select,delete on public.mblite_forum to authenticated;
grant insert(user_id,author,title,body,tag,image_data,parent_id) on public.mblite_forum to authenticated;
grant update(suspended) on public.mblite_forum to authenticated;
create policy forum_read on public.mblite_forum for select to authenticated using(not suspended or mblite_access_private.community_admin());
create policy forum_insert on public.mblite_forum for insert to authenticated with check(user_id=auth.uid());
create policy forum_delete on public.mblite_forum for delete to authenticated using(user_id=auth.uid() or mblite_access_private.community_admin());
create policy forum_moderate on public.mblite_forum for update to authenticated using(mblite_access_private.community_admin()) with check(mblite_access_private.community_admin());
create table public.mblite_forum_recommend(post_id uuid references public.mblite_forum on delete cascade,user_id uuid references auth.users on delete cascade,primary key(post_id,user_id));
alter table public.mblite_forum_recommend enable row level security;
revoke all on public.mblite_forum_recommend from public,anon,authenticated;
grant select,insert,delete on public.mblite_forum_recommend to authenticated;
create policy forum_rec_read on public.mblite_forum_recommend for select to authenticated using(true);
create policy forum_rec_insert on public.mblite_forum_recommend for insert to authenticated with check(user_id=auth.uid());
create policy forum_rec_delete on public.mblite_forum_recommend for delete to authenticated using(user_id=auth.uid());
alter table public.mblite_comments add column suspended boolean not null default false;
drop policy mblite_comments_read on public.mblite_comments;
create policy mblite_comments_read on public.mblite_comments for select to authenticated using(not suspended or mblite_access_private.community_admin());
create policy mblite_comments_admin_delete on public.mblite_comments for delete to authenticated using(mblite_access_private.community_admin());
grant update(suspended) on public.mblite_comments to authenticated;
create policy mblite_comments_admin_update on public.mblite_comments for update to authenticated using(mblite_access_private.community_admin()) with check(mblite_access_private.community_admin());
alter table public.mblite_votes add column voted_at timestamptz;
create function public.mblite_vote_timestamp() returns trigger language plpgsql set search_path='' as $$ begin new.voted_at=now();return new;end $$;
create trigger mblite_vote_timestamp before insert or update on public.mblite_votes for each row execute function public.mblite_vote_timestamp();
create table public.mblite_tier_votes(user_id uuid references auth.users on delete cascade,book_id text references public.mblite_books on delete cascade,level smallint not null check(level between 1 and 5),primary key(user_id,book_id));
alter table public.mblite_tier_votes enable row level security;
revoke all on public.mblite_tier_votes from public,anon,authenticated;
grant select,insert,update,delete on public.mblite_tier_votes to authenticated;
create policy tier_read on public.mblite_tier_votes for select to authenticated using(true);
create policy tier_insert on public.mblite_tier_votes for insert to authenticated with check(user_id=auth.uid());
create policy tier_update on public.mblite_tier_votes for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy tier_delete on public.mblite_tier_votes for delete to authenticated using(user_id=auth.uid());
create table public.mblite_tier_labels(level smallint primary key check(level between 1 and 5),label text not null check(length(label) between 1 and 40));
insert into public.mblite_tier_labels values(1,'A'),(2,'B'),(3,'C'),(4,'D'),(5,'E');
alter table public.mblite_tier_labels enable row level security;
revoke all on public.mblite_tier_labels from public,anon,authenticated;
grant select,update(label) on public.mblite_tier_labels to authenticated;
create policy tier_labels_read on public.mblite_tier_labels for select to authenticated using(true);
create policy tier_labels_admin on public.mblite_tier_labels for update to authenticated using(mblite_access_private.community_admin()) with check(mblite_access_private.community_admin());
create function mblite_access_private.community_accounts() returns jsonb language plpgsql security definer set search_path='' as $$ begin if not mblite_access_private.community_admin() then raise exception 'Acesso negado'; end if; return coalesce((select jsonb_agg(to_jsonb(a)) from (select id,email,created_at,last_sign_in_at,email_confirmed_at,created_at < '2027-01-21 00:00:00 America/Bahia'::timestamptz as early_access from auth.users where not is_anonymous order by created_at desc limit 500)a),'[]'::jsonb);end $$;
revoke all on function mblite_access_private.community_accounts() from public,anon,authenticated;
grant execute on function mblite_access_private.community_accounts() to authenticated;
create function public.mblite_community_accounts() returns jsonb language sql security invoker set search_path='' as $$ select mblite_access_private.community_accounts() $$;
revoke all on function public.mblite_community_accounts() from public,anon,authenticated;
grant execute on function public.mblite_community_accounts() to authenticated;
commit;